export function attachSoundWorkshop({getLanguage=()=> 'EN'}={}){
 const langs=['EN','HU','DE','FR','ES','IT','PT','PL'],w={title:'Sound workshop|Hangműhely|Klangwerkstatt|Atelier sonore|Taller de sonido|Laboratorio audio|Oficina de som|Pracownia dźwięku',intro:'Included narration, ambience, effects and music starters; local favorites, saved moods and explicit transfer to your video timeline.|Beépített narrációk, háttérhangok, effektek és zenei minták; helyi kedvencek, mentett hangulatok és átküldés a videó idővonalára.|Sprech-, Atmosphären-, Effekt- und Musikproben; Favoriten, Stimmungen und Übergabe an Videozeitleiste.|Narrations, ambiances, effets et musiques ; favoris, ambiances et transfert vidéo.|Narración, ambientes, efectos y música; favoritos, ambientes guardados y envío al vídeo.|Narrazioni, ambienti, effetti e musica; preferiti, atmosfere e invio al video.|Narrações, ambientes, efeitos e música; favoritos, ambientes e envio para vídeo.|Narracje, otoczenie, efekty i muzyka; ulubione, nastroje i przesyłanie do filmu.',open:'Open Sound workshop|Hangműhely megnyitása|Klangwerkstatt öffnen|Ouvrir atelier sonore|Abrir taller de sonido|Apri laboratorio audio|Abrir oficina de som|Otwórz pracownię dźwięku',error:'Restart the updated Studio server and refresh this page.|Indítsd újra a frissített Studio-szervert, majd frissítsd ezt a lapot.|Aktualisierten Studio-Server neu starten und Seite aktualisieren.|Redémarrez le serveur Studio à jour et actualisez.|Reinicia el servidor actualizado y recarga.|Riavvia il server aggiornato e ricarica.|Reinicie servidor atualizado e atualize.|Uruchom ponownie zaktualizowany serwer i odśwież.'};const text=k=>w[k].split('|')[Math.max(0,langs.indexOf(getLanguage()))],host=document.getElementById('video-workshop')||document.getElementById('image-workshop');if(!host)return null;const root=document.createElement('section'),title=document.createElement('h2'),intro=document.createElement('p'),button=document.createElement('button'),status=document.createElement('p');root.id='sound-workshop';root.style.cssText='padding:20px;margin:18px 0;border:1px solid #496777;border-radius:16px;background:var(--panel,#142734)';button.id='sound-workshop-launcher';button.type='button';root.append(title,intro,button,status);host.after(root);const refresh=()=>{title.textContent=text('title');intro.textContent=text('intro');button.textContent=text('open');};button.addEventListener('click',async()=>{try{const r=await fetch('/health');if(!(await r.json()).soundWorkshop)throw Error();window.open('/sound-workshop?lang='+encodeURIComponent(langs.includes(getLanguage())?getLanguage():'EN'),'_blank','noopener');status.textContent='';}catch{status.textContent=text('error');}});document.getElementById('ui-language')?.addEventListener('change',refresh);refresh();return {refresh};
}
